import {createContext, memo, useCallback, useMemo, useRef, useState} from 'react'

import type {IssueField} from '../../api/common-contracts'
import {apiGetSuggestedIssueFields} from '../../api/memex/api-get-suggested-issue-fields'
import {getInitialState} from '../../helpers/initial-state'
import {ViewerPrivileges} from '../../helpers/viewer-privileges'
import {useEnabledFeatures} from '../../hooks/use-enabled-features'
import {useAllColumns} from '../columns/use-all-columns'

type IssueFieldLoadingState = 'idle' | 'loading' | 'error' | 'success'

export type IssueFieldsContextType = {
  /** Indicates whether issue fields feature is enabled and the user is in an organization context */
  issueFieldsEnabled: boolean

  /** Suggested issue fields for an organization */
  suggestedIssueFields: Array<IssueField>

  /** Loading state for issue suggestions */
  suggestionsLoadingState: IssueFieldLoadingState

  /** Load issue field suggestions if issue fields are enabled */
  loadIssueFieldSuggestionsIfNeeded: () => Promise<void>

  /** Indicates whether issue fields suggestions have been loaded */
  hasLoadedSuggestions: boolean
}

export const IssueFieldsContext = createContext<IssueFieldsContextType | null>(null)

/** Reload issue field suggestions after 5 minutes */
export const SuggestionsCacheMs = 5 * 60 * 1000

export const IssueFieldsStateProvider = memo<{children: React.ReactNode}>(function IssueFieldsStateProvider({
  children,
}) {
  const [suggestionsLoadingState, setSuggestionsLoadingState] = useState<IssueFieldLoadingState>('idle')
  const {project_issue_fields} = useEnabledFeatures()
  const {isOrganization} = getInitialState()
  const {hasWritePermissions} = ViewerPrivileges()
  const issueFieldsEnabled = Boolean(project_issue_fields && isOrganization)
  const lastUpdatedRef = useRef<DOMHighResTimeStamp | null>(null)
  const shouldLoadIssueFieldSuggestions =
    ['idle', 'error'].includes(suggestionsLoadingState) && issueFieldsEnabled && hasWritePermissions
  const hasLoadedSuggestions = useRef(false)

  const shouldBustSuggestionsCache = useCallback(() => {
    if (!issueFieldsEnabled || !hasWritePermissions || suggestionsLoadingState === 'loading') return false
    if (lastUpdatedRef.current === null) return true
    return window.performance.now() - lastUpdatedRef.current >= SuggestionsCacheMs
  }, [issueFieldsEnabled, suggestionsLoadingState, hasWritePermissions])

  const [issueFields, setIssueFields] = useState<Array<IssueField>>([])
  const {allColumns} = useAllColumns()
  // Convert this to a primitive to avoid re-computing issue fields whenever allColumns changes
  const usedIssueFieldIds = allColumns
    .filter(col => col.issueFieldId)
    .map(col => col.issueFieldId)
    .join(',')

  const usedIssueFieldSet = useMemo(
    () => new Set(usedIssueFieldIds.split(',').map(id => Number(id))),
    [usedIssueFieldIds],
  )

  const loadIssueFieldSuggestions = useCallback(async () => {
    if (suggestionsLoadingState === 'loading') return

    setSuggestionsLoadingState('loading')

    try {
      const res = await apiGetSuggestedIssueFields()
      setIssueFields(res.issue_fields)
      setSuggestionsLoadingState('success')
      hasLoadedSuggestions.current = true
    } catch {
      setSuggestionsLoadingState('error')
    } finally {
      lastUpdatedRef.current = window.performance.now()
    }
  }, [suggestionsLoadingState])

  const suggestedIssueFields = useMemo(() => {
    return issueFields.filter(field => !usedIssueFieldSet.has(field.id))
  }, [issueFields, usedIssueFieldSet])

  const loadIssueFieldSuggestionsIfNeeded = useCallback(async () => {
    if (shouldLoadIssueFieldSuggestions || shouldBustSuggestionsCache()) {
      await loadIssueFieldSuggestions()
    }
  }, [shouldLoadIssueFieldSuggestions, loadIssueFieldSuggestions, shouldBustSuggestionsCache])

  const contextValue: IssueFieldsContextType = useMemo(() => {
    return {
      suggestionsLoadingState,
      suggestedIssueFields,
      issueFieldsEnabled,
      loadIssueFieldSuggestionsIfNeeded,
      hasLoadedSuggestions: hasLoadedSuggestions.current,
    }
  }, [suggestionsLoadingState, suggestedIssueFields, issueFieldsEnabled, loadIssueFieldSuggestionsIfNeeded])

  return <IssueFieldsContext.Provider value={contextValue}>{children}</IssueFieldsContext.Provider>
})

try{ IssueFieldsContext.displayName ||= 'IssueFieldsContext' } catch {}
try{ IssueFieldsStateProvider.displayName ||= 'IssueFieldsStateProvider' } catch {}