import {useContext} from 'react'

import {IssueFieldsContext} from './issue-fields-provider'

/**
 * Accesses the IssueFieldsContext, which contains state related to the issue fields
 * of a project. Consuming this context will cause a component to re-render
 * any time the state changes.
 * @returns The value of the IssueFieldsContext
 */
export const useIssueFields = () => {
  const context = useContext(IssueFieldsContext)
  if (!context) {
    throw new Error('useIssueFieldsContext must be used within an IssueFieldsContext.Provider')
  }

  return context
}
