import {MemexColumnDataType} from '../api/columns/contracts/memex-column'
import {ItemType} from '../api/memex-items/item-type'
import {isPullRequestColumn, isValueEditableColumn} from '../models/column-capabilities'
import {getEnabledFeatures} from './feature-flags'
import {getInitialState} from './initial-state'

// Capture these values in module scope to avoid repeated calls
let projectOwner: string | undefined = undefined
let issueFieldsEditable: boolean | undefined = undefined

export function resetIssueFieldCache() {
  projectOwner = undefined
  issueFieldsEditable = undefined
}

export function issueTypeValuesAllowed(contentType: ItemType, contentOwner: string) {
  if (contentType !== ItemType.Issue) {
    return false
  }

  if (issueFieldsEditable === undefined) {
    const {project_issue_fields_editing} = getEnabledFeatures()
    issueFieldsEditable = project_issue_fields_editing
  }

  if (!issueFieldsEditable) {
    return false
  }

  if (projectOwner === undefined) {
    projectOwner = getInitialState().projectOwner?.login || ''
  }

  if (!projectOwner || !contentOwner) {
    return false
  }

  return projectOwner.toLowerCase() === contentOwner.toLowerCase()
}

export function columnEditable(
  itemType: ItemType,
  contentOwner: string,
  columnType: MemexColumnDataType,
  isIssueField: boolean,
) {
  // These column data types are never editable
  if (!isValueEditableColumn(columnType)) {
    return false
  }

  if (itemType === ItemType.RedactedItem) {
    return false
  }

  if (itemType === ItemType.PullRequest && !isPullRequestColumn(columnType)) {
    return false
  }

  // Parent issue does not support the "Convert to issue" flow like other issues only columns
  if (columnType === MemexColumnDataType.ParentIssue && itemType === ItemType.DraftIssue) {
    return false
  }

  // Items cannot be transferred to new repositories from within projects
  if (columnType === MemexColumnDataType.Repository && itemType !== ItemType.DraftIssue) {
    return false
  }

  if (isIssueField) {
    return issueTypeValuesAllowed(itemType, contentOwner)
  }

  return true
}
